// Generated by scripts/build.mjs.
const { Plugin, CodeBlock, Style } = require('@opencode/plugin/gui')
const { createComponent, createEffect, onMount } = require('solid-js')
const { insert } = require('solid-js/web')
const styles = "/* Only take over layout after the renderer finds the host's original pre and Copy. */\n[data-component=\"markdown\"] [data-component=\"markdown-code\"]:has(> [data-slot=\"markdown-code-content\"] [data-ocx-code-header]) {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto auto;\n  align-items: center;\n  min-width: 0;\n  margin-block: 12px 24px;\n  border: 0.5px solid var(--v2-border-border-muted);\n  border-radius: 8px;\n  background: var(--v2-background-bg-layer-01);\n\n  > [data-slot=\"markdown-code-content\"] { grid-area: 1 / 1; min-width: 0; margin: 0; }\n  > [data-slot=\"markdown-code-actions\"] { grid-area: 1 / 2; }\n  > [data-slot=\"markdown-copy-button\"] { grid-area: 1 / 3; margin-inline: 2px 6px; }\n  > :is([data-slot=\"markdown-copy-button\"], [data-slot=\"markdown-code-actions\"]) {\n    position: static;\n    opacity: 1;\n    justify-self: end;\n  }\n  > pre {\n    display: block;\n    grid-area: 2 / 1 / 3 / -1;\n    min-width: 0;\n    margin: 0;\n    border: 0;\n    border-top: 0.5px solid var(--v2-border-border-muted);\n    border-radius: 0 0 8px 8px;\n    white-space: pre;\n    overflow-x: auto;\n  }\n  &:has([data-ocx-code-header] button[aria-pressed=\"true\"]) > pre {\n    white-space: pre-wrap;\n    overflow-wrap: anywhere;\n    & code, & code span { white-space: inherit; }\n  }\n\n  /* Desktop flattens Shell spans with an important color. Restore the role\n     emitted by its tokenizer through the variable that rule already reads. */\n  &[data-code-kind=\"shell\"] > pre code {\n    span[style*=\"var(--syntax-keyword)\"] { --markdown-shell-code-token-color: var(--syntax-keyword); }\n    span[style*=\"var(--syntax-primitive)\"] { --markdown-shell-code-token-color: var(--syntax-primitive); }\n    span[style*=\"var(--syntax-string)\"] { --markdown-shell-code-token-color: var(--syntax-string); }\n    span[style*=\"var(--syntax-type)\"] { --markdown-shell-code-token-color: var(--syntax-type); }\n    span[style*=\"var(--syntax-constant)\"] { --markdown-shell-code-token-color: var(--syntax-constant); }\n    span[style*=\"var(--syntax-comment)\"] { --markdown-shell-code-token-color: var(--syntax-comment); }\n    span[style*=\"var(--syntax-variable)\"] { --markdown-shell-code-token-color: var(--syntax-variable); }\n    span[style*=\"var(--syntax-operator)\"] { --markdown-shell-code-token-color: var(--syntax-operator); }\n    span[style*=\"var(--syntax-punctuation)\"] { --markdown-shell-code-token-color: var(--syntax-punctuation); }\n    span[style*=\"var(--syntax-property)\"] { --markdown-shell-code-token-color: var(--syntax-property); }\n    span[style*=\"var(--syntax-regexp)\"] { --markdown-shell-code-token-color: var(--syntax-regexp); }\n    span[style*=\"var(--syntax-info)\"] { --markdown-shell-code-token-color: var(--syntax-info); }\n  }\n}\n\n[data-ocx-code-header] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 6px;\n  min-width: 0;\n  min-height: 34px;\n  padding-inline: 12px 2px;\n  color: var(--v2-text-text-muted);\n  font-size: 12px;\n  user-select: none;\n\n  > span { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-weight: 550; }\n  > button {\n    flex: none;\n    padding: 3px 7px;\n    border-radius: 4px;\n    color: inherit;\n    line-height: 18px;\n    cursor: pointer;\n  }\n  > button:hover { background: var(--v2-overlay-simple-overlay-hover); }\n  > button[aria-pressed=\"true\"] {\n    background: var(--v2-overlay-simple-overlay-pressed);\n    color: var(--v2-text-text-accent);\n  }\n  > button:focus-visible { outline: 2px solid var(--v2-border-border-focus); outline-offset: 1px; }\n}\n"

const labels = {
  ts: 'TypeScript', typescript: 'TypeScript', tsx: 'TSX',
  js: 'JavaScript', javascript: 'JavaScript', jsx: 'JSX',
  py: 'Python', python: 'Python',
  sh: 'Shell', shell: 'Shell', bash: 'Bash', zsh: 'Zsh',
}

function toolbar(ctx, block) {
  const header = document.createElement('div')
  const language = document.createElement('span')
  language.textContent = labels[block.language]
  const wrap = document.createElement('button')
  wrap.type = 'button'
  wrap.setAttribute('aria-pressed', 'false')
  wrap.onclick = () => wrap.setAttribute('aria-pressed', String(wrap.getAttribute('aria-pressed') !== 'true'))
  createEffect(() => { wrap.textContent = ctx.t('wrap') })
  header.append(language, wrap)
  onMount(() => {
    // Desktop keeps the highlighted pre and native Copy when it mounts our renderer.
    const slot = header.closest('[data-slot="markdown-code-content"]')
    const fence = slot?.parentElement
    if (fence?.matches('[data-component="markdown-code"]') &&
        fence.querySelector(':scope > pre > code') && fence.querySelector(':scope > [data-slot="markdown-copy-button"]')) {
      header.dataset.ocxCodeHeader = ''
      return
    }
    // A different host layout must still show the source via the public Code component.
    header.replaceChildren()
    insert(header, () => createComponent(ctx.ui.Code, { content: block.code, language: block.language }))
  })
  return header
}

exports.default = Plugin.define({
  i18n: { en: { wrap: 'Wrap lines' }, zh: { wrap: '自动换行' }, zht: { wrap: '自動換行' } },
  setup(ctx) {
    ctx.add(Style, styles)
    ctx.add(CodeBlock, { languages: Object.keys(labels), render: block => toolbar(ctx, block) })
  },
})
